def _intervallo_duale_summary(temp_nuova_min, temp_nuova_max, temp_trasf_min, temp_trasf_max):
    intervalli = []
    testo_nuova = _testo_range(temp_nuova_min, temp_nuova_max, "°C")
    testo_trasf = _testo_range(temp_trasf_min, temp_trasf_max, "°C")
    if testo_nuova != "—":
        intervalli.append(("❄️", "Neve nuova", testo_nuova))
    if testo_trasf != "—":
        intervalli.append(("✳️", "Neve trasformata", testo_trasf))
    return intervalli


def _range_overlap(min_prod, max_prod, sel_min, sel_max):
    min_eff = float('-inf') if pd.isna(min_prod) else float(min_prod)
    max_eff = float('inf') if pd.isna(max_prod) else float(max_prod)
    return min_eff <= float(sel_max) and max_eff >= float(sel_min)


MAX_FOTO_PRODOTTO_MB = 5
MIME_FOTO_AMMESSI = {"image/jpeg", "image/png", "image/webp"}


def _prepara_foto_upload(file_caricato):
    if file_caricato is None:
        return "", "", ""

    mime = str(getattr(file_caricato, "type", "") or "").lower()
    nome = str(getattr(file_caricato, "name", "") or "foto_prodotto").strip()
    dati = file_caricato.getvalue()

    if mime not in MIME_FOTO_AMMESSI:
        raise ValueError("Formato foto non supportato. Usa JPG, PNG oppure WEBP.")

    limite = MAX_FOTO_PRODOTTO_MB * 1024 * 1024
    if len(dati) > limite:
        raise ValueError(
            f"La foto è troppo grande. Dimensione massima: {MAX_FOTO_PRODOTTO_MB} MB."
        )

    return base64.b64encode(dati).decode("ascii"), mime, nome


def _mostra_foto_db(foto_data, use_container_width=True, width=None):
    if foto_data is None:
        return False
    try:
        if isinstance(foto_data, (bytes, bytearray, memoryview)):
            dati = bytes(foto_data)
        else:
            valore = str(foto_data or "").strip()
            if not valore:
                return False
            dati = base64.b64decode(valore)

        if not dati:
            return False
        if width is not None:
            st.image(dati, width=width)
        else:
            st.image(dati, use_container_width=use_container_width)
        return True
    except Exception:
        return False



MAX_FOTO_TEST_INPUT_MB = 15
TARGET_FOTO_TEST_KB = 550


def _normalizza_orientamento_foto_test(dati_in, max_dim=None, quality=88):
    """Restituisce JPEG con orientamento EXIF applicato fisicamente ai pixel."""
    from io import BytesIO
    from PIL import Image, ImageOps

    img = Image.open(BytesIO(dati_in))
    img.load()

    # Alcuni telefoni memorizzano la rotazione solo nel tag EXIF Orientation.
    # exif_transpose applica quella rotazione ai pixel e rimuove il tag, evitando
    # che browser/Streamlit mostrino la foto ruotata o la ruotino una seconda volta.
    try:
        img = ImageOps.exif_transpose(img)
    except Exception:
        # Fallback manuale per file con EXIF parzialmente corrotti.
        try:
            orientation = int(img.getexif().get(274, 1) or 1)
            if orientation == 2:
                img = ImageOps.mirror(img)
            elif orientation == 3:
                img = img.rotate(180, expand=True)
            elif orientation == 4:
                img = ImageOps.flip(img)
            elif orientation == 5:
                img = ImageOps.mirror(img.rotate(-90, expand=True))
            elif orientation == 6:
                img = img.rotate(-90, expand=True)
            elif orientation == 7:
                img = ImageOps.mirror(img.rotate(90, expand=True))
            elif orientation == 8:
                img = img.rotate(90, expand=True)
        except Exception:
            pass

    if img.mode not in ("RGB", "L"):
        if "A" in img.getbands():
            fondo = Image.new("RGB", img.size, "white")
            alpha = img.getchannel("A")
            fondo.paste(img.convert("RGB"), mask=alpha)
            img = fondo
        else:
            img = img.convert("RGB")
    elif img.mode == "L":
        img = img.convert("RGB")

    if max_dim:
        img.thumbnail((int(max_dim), int(max_dim)), Image.Resampling.LANCZOS)

    buf = BytesIO()
    img.save(buf, format="JPEG", quality=int(quality), optimize=True, progressive=True)
    return buf.getvalue(), img.size


def _anteprima_foto_test_upload(file_caricato, width=230):
    """Anteprima con orientamento normalizzato, coerente con il file che verrà salvato."""
    if file_caricato is None:
        return
    try:
        dati = file_caricato.getvalue()
        dati_preview, _ = _normalizza_orientamento_foto_test(dati, max_dim=900, quality=86)
        st.image(dati_preview, width=width)
    except Exception:
        # Fallback: se Pillow non riesce a leggere il file, lascia a Streamlit
        # la visualizzazione originale invece di bloccare il form.
        st.image(file_caricato, width=width)


def _prepara_foto_test_upload(file_caricato):
    """Comprimi una foto pista/neve prima di salvarla nel DB."""
    if file_caricato is None:
        return None

    mime_in = str(getattr(file_caricato, "type", "") or "").lower()
    nome_in = str(getattr(file_caricato, "name", "") or "foto_test").strip()
    dati_in = file_caricato.getvalue()
    if mime_in not in MIME_FOTO_AMMESSI:
        raise ValueError("Formato foto non supportato. Usa JPG, PNG oppure WEBP.")
    if len(dati_in) > MAX_FOTO_TEST_INPUT_MB * 1024 * 1024:
        raise ValueError(
            f"La foto è troppo grande. Dimensione massima in ingresso: {MAX_FOTO_TEST_INPUT_MB} MB."
        )

    # Normalizziamo SEMPRE l'orientamento prima della compressione. In questo modo
    # il file salvato non dipende più dal tag EXIF Orientation del telefono.
    try:
        dati_out, dimensioni = _normalizza_orientamento_foto_test(
            dati_in, max_dim=1600, quality=84
        )
        target = TARGET_FOTO_TEST_KB * 1024

        if len(dati_out) > target:
            for quality in (80, 76, 72, 68, 64, 60):
                dati_out, dimensioni = _normalizza_orientamento_foto_test(
                    dati_in, max_dim=1600, quality=quality
                )
                if len(dati_out) <= target:
                    break

        # Se resta pesante, riduciamo ulteriormente la risoluzione.
        if len(dati_out) > target and max(dimensioni) > 1350:
            dati_out, _ = _normalizza_orientamento_foto_test(
                dati_in, max_dim=1350, quality=68
            )

        nome_base = re.sub(r"\.[^.]+$", "", nome_in) or "foto_test"
        return base64.b64encode(dati_out).decode("ascii"), "image/jpeg", f"{nome_base}.jpg"
    except Exception:
        if len(dati_in) > 1200 * 1024:
            raise ValueError("Non riesco a comprimere questa foto. Prova con un JPG o PNG più leggero.")
        return base64.b64encode(dati_in).decode("ascii"), mime_in, nome_in


def _foto_test_correnti(sessione_id):
    if sessione_id is None:
        return {}
    df = leggi_df(
        """SELECT foto_pista_data, foto_pista_mime, foto_pista_nome,
                  foto_neve_data, foto_neve_mime, foto_neve_nome
           FROM sessioni WHERE id = ?""",
        (int(sessione_id),),
    )
    return {} if df.empty else df.iloc[0].to_dict()


def _render_foto_test_form(prefix, sessione_id=None):
    """Due uploader opzionali: pista generale e dettaglio neve."""
    correnti = _foto_test_correnti(sessione_id)
    st.markdown('<div class="insert-test-divider"></div>', unsafe_allow_html=True)
    st.markdown("#### Foto pista / neve")
    st.caption(
        "Facoltative. Le immagini vengono compresse automaticamente prima del salvataggio. "
        "Consiglio: una foto generale della pista e una ravvicinata della neve."
    )
    c1, c2 = st.columns(2)
    with c1:
        if str(correnti.get("foto_pista_data") or "").strip():
            st.caption("Foto pista attuale")
            _mostra_foto_db(correnti.get("foto_pista_data"), width=230)
        foto_pista_upload = st.file_uploader(
            "Foto pista",
            type=["jpg", "jpeg", "png", "webp"],
            key=f"{prefix}_foto_pista_upload",
            help="Foto generale della pista/superficie. Se sei in modifica e non carichi nulla, la foto attuale resta invariata.",
        )
        if foto_pista_upload is not None:
            _anteprima_foto_test_upload(foto_pista_upload, width=230)
    with c2:
        if str(correnti.get("foto_neve_data") or "").strip():
            st.caption("Dettaglio neve attuale")
            _mostra_foto_db(correnti.get("foto_neve_data"), width=230)
        foto_neve_upload = st.file_uploader(
            "Foto dettaglio neve",
            type=["jpg", "jpeg", "png", "webp"],
            key=f"{prefix}_foto_neve_upload",
            help="Foto ravvicinata del grano e della superficie. Se sei in modifica e non carichi nulla, la foto attuale resta invariata.",
        )
        if foto_neve_upload is not None:
            _anteprima_foto_test_upload(foto_neve_upload, width=230)
    return foto_pista_upload, foto_neve_upload


def _prepara_foto_test_doppia(foto_pista_upload, foto_neve_upload):
    return (
        _prepara_foto_test_upload(foto_pista_upload),
        _prepara_foto_test_upload(foto_neve_upload),
    )


def _aggiorna_foto_test_conn(conn, sessione_id, foto_pista_preparata, foto_neve_preparata):
    aggiornamenti = []
    valori = []
    if foto_pista_preparata is not None:
        aggiornamenti += ["foto_pista_data = ?", "foto_pista_mime = ?", "foto_pista_nome = ?"]
        valori.extend(foto_pista_preparata)
    if foto_neve_preparata is not None:
        aggiornamenti += ["foto_neve_data = ?", "foto_neve_mime = ?", "foto_neve_nome = ?"]
        valori.extend(foto_neve_preparata)
    if aggiornamenti:
        valori.append(int(sessione_id))
        conn.execute(
            f"UPDATE sessioni SET {', '.join(aggiornamenti)} WHERE id = ?",
            tuple(valori),
        )


def _aggiorna_foto_test_sessione(sessione_id, foto_pista_preparata, foto_neve_preparata):
    if foto_pista_preparata is None and foto_neve_preparata is None:
        return
    conn = apri_connessione_database()
    try:
        _aggiorna_foto_test_conn(conn, sessione_id, foto_pista_preparata, foto_neve_preparata)
        conn.commit()
    finally:
        conn.close()
    _invalida_cache_dati()


