def _foto_catalogo_ids(categoria, ids):
    """Recupera/decodifica solo le foto necessarie e le conserva nella sessione."""
    ids_puliti = []
    for valore in ids or []:
        try:
            ident = int(valore)
        except Exception:
            continue
        if ident not in ids_puliti:
            ids_puliti.append(ident)
    if not ids_puliti:
        return {}

    chiave = f"_catalog_photo_bytes_{categoria}"
    cache = st.session_state.setdefault(chiave, {})
    mancanti = [ident for ident in ids_puliti if ident not in cache]

    # Blocchi piccoli: evita query enormi e riduce il traffico Turso quando
    # un filtro mostra solo pochi prodotti.
    for i in range(0, len(mancanti), 80):
        blocco = mancanti[i:i + 80]
        if not blocco:
            continue
        placeholders = ",".join(["?"] * len(blocco))
        foto_df = leggi_df(
            f"SELECT id, foto_data FROM catalogo_prodotti WHERE categoria = ? AND id IN ({placeholders})",
            tuple([categoria] + blocco),
        )
        trovati = set()
        for record in foto_df.to_dict("records"):
            ident = int(record["id"])
            trovati.add(ident)
            valore = str(record.get("foto_data") or "").strip()
            if valore:
                try:
                    cache[ident] = base64.b64decode(valore)
                except Exception:
                    cache[ident] = None
            else:
                cache[ident] = None
        # Memorizza anche gli ID senza immagine per non richiederli di nuovo.
        for ident in blocco:
            if ident not in trovati:
                cache[ident] = None

    return {ident: cache.get(ident) for ident in ids_puliti if cache.get(ident)}


def _foto_catalogo_sessione(categoria):
    """Compatibilità: carica l'intera categoria solo dove è realmente richiesta."""
    ids_df = leggi_df("SELECT id FROM catalogo_prodotti WHERE categoria = ?", (categoria,))
    ids = ids_df["id"].tolist() if not ids_df.empty else []
    return _foto_catalogo_ids(categoria, ids)


